/* Décors de base */
function fondDehors(u, ciel, sol, extras = '') {
  return `<defs>${degrade(`${u}a`, ciel)}${degrade(`${u}b`, sol)}</defs><rect width="800" height="600" fill="url(#${u}a)"/>${extras}<path d="M0 ${380}Q200 350 400 376T800 362V600H0Z" fill="url(#${u}b)"/>`;
}
function fondInterieur(u, mur, parquet, extras = '', hauteur = 440) {
  return `<defs>${degrade(`${u}a`, mur)}${degrade(`${u}p`, parquet)}</defs><rect width="800" height="${hauteur}" fill="url(#${u}a)"/>${extras}<rect y="${hauteur}" width="800" height="${600 - hauteur}" fill="url(#${u}p)"/><rect y="${hauteur - 6}" width="800" height="10" fill="#f4f1e8"/>`;
}
const herbes = (g, n = 60, y0 = 400, c = '#5e9a63') => { const r = aleaScene(g); let s = ''; for (let i = 0; i < n; i++) { const x = (r() * 800).toFixed(0), y = (y0 + r() * (590 - y0)).toFixed(0); s += `<path d="M${x} ${y}q-3-9-6-12M${x} ${y}q1-10 3-14" stroke="${c}" stroke-width="2" fill="none"/>`; } return s; };
